import { Table, StringColumn, TableNameColumn } from '../../db'

export const sys_journal_field = Table({
    allowWebServiceAccess: true,
    attributes: {
        no_archive: true,
        no_update: true,
    },
    label: 'Journal Entry',
    name: 'sys_journal_field',
    schema: {
        element: StringColumn({ maxLength: 40 }),

        value: StringColumn({
            label: 'Value',
            maxLength: 8000,
        }),
        name: TableNameColumn({}),

        element_id: StringColumn({ maxLength: 32 }),
    },
})
